    return os.environ.get('PULSO_DB', 'pulso.db')


@contextmanager
def conexion():
    con = sqlite3.connect(ruta())
    con.row_factory = sqlite3.Row
    con.execute('PRAGMA foreign_keys = ON')
    try:
        yield con
        con.commit()
    finally:
        con.close()


@contextmanager
def transaccion():
    """Una transacción que toma el lock de escritura desde el principio.

    Dentro hay que usar las funciones `*_en(con, ...)` con el `con` que devuelve esto:
    las otras conexiones no ven lo que todavía no se confirmó.
    """
    with conexion() as con:
        con.execute('BEGIN IMMEDIATE')
        yield con


def inicializar():
    with conexion() as con:
        con.executescript(ESQUEMA)


