def _asignar_lugares(con, clase, pendientes):
    """Pasa los lugares libres de la clase al primero de la lista de espera.

    Dentro de la transacción de quien libera el lugar. Los correos se acumulan en
    `pendientes` y se mandan después del commit con `_enviar()`.
    """
    ahora = reloj.ahora()
    inicio = db.a_fecha(clase['inicio'])
    if inicio <= ahora:
        return
    while db.confirmadas_en(con, clase['id']) < clase['cupo']:
        primero = db.primero_en_espera_en(con, clase['id'])
        if primero is None:
            return
        db.quitar_de_espera_en(con, primero['id'])
        socio = db.socio_en(con, primero['socio_id'])
        if db.tiene_confirmada_en(con, socio['id'], clase['id']):
            continue
        asunto_fecha = f"{clase['nombre']} el {correo.fecha_y_hora(inicio)}"
        if socio['creditos'] < 1:
            pendientes.append((socio['email'], f'No pudimos darte el lugar: {asunto_fecha}',
                               f"Hola {socio['nombre']}, se liberó un lugar en {clase['nombre']} "
                               'pero no te quedan créditos, así que pasamos al siguiente de la lista.'))
            continue
        db.insertar_reserva_en(con, socio['id'], clase['id'], ahora)
        db.sumar_creditos_en(con, socio['id'], -1)
        pendientes.append((socio['email'], f'Se liberó un lugar: {asunto_fecha}',
